package com.gameaggregator.releaseservice.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="releases") public class Release{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID gameId;@Column(nullable=false)public UUID versionId;@Column(nullable=false)public UUID buildId;@Column(nullable=false)public String channel;@Column(nullable=false)public String status="DRAFT";@Lob @Column(nullable=false)public String releaseNotes;public UUID createdBy;public UUID approvedBy;public Instant approvedAt;public Instant releasedAt;public UUID rollbackOfReleaseId;@Column(nullable=false)public Instant createdAt=Instant.now();@Version public long revision;protected Release(){}public Release(UUID g,UUID v,UUID b,String c,String n,UUID u){gameId=g;versionId=v;buildId=b;channel=c;releaseNotes=n;createdBy=u;}}